export const BASE_TEMPLATE = {
    port: 0, // Will be assigned
    // `dependsOn` is the current name; `dependencies` is deprecated and `flisk doctor` warns about it, so a fresh scaffold must not write it.
    dependsOn: [],
    build: {
        dockerfile: "Dockerfile",
        context: ".",
    },
    dev: {
        command: "bun run dev",
        watch: ["src/**/*"],
    },
};
export const TYPE_SPECIFIC = {
    backend: {
        healthCheckPath: "/health",
    },
    frontend: {
        dev: {
            command: "bun run dev",
            watch: ["src/**/*", "public/**/*"],
        },
    },
    worker: {
        dev: {
            command: "bun run worker",
            watch: ["src/**/*"],
        },
    },
    mcp: {
        healthCheckPath: "/health",
    },
    // /ready is the readiness route (checkpoint store reachable); /health is liveness only, so an idle agent stays healthy.
    agent: {
        healthCheckPath: "/health",
    },
    [BRING_YOUR_OWN_TYPE]: {
        healthCheckPath: "/health",
    },
};
const BYO_RESTART_POLICIES = ["no", "on-failure", "unless-stopped", "always"];
export function resolveByoPort(value, assignedPort, resources) {
    return resolveResourcePort(BRING_YOUR_OWN_TYPE, value, assignedPort, resources);
}
// `--port` is an override for every port-assigned type, validated against that type's range.
// Without it the next free port in the type's range is used.
export function resolveResourcePort(resourceType, value, assignedPort, resources) {
    if (!value)
        return assignedPort;
    const { min, max } = PORT_RANGES[resourceType];
    const flag = resourceType === BRING_YOUR_OWN_TYPE ? "BYO --port" : "--port";
    const subject = resourceType === BRING_YOUR_OWN_TYPE ? "BYO port" : "Port";
    if (!/^\d+$/.test(value)) {
        throw new TdkError(`${flag} must be an integer from ${min} through ${max}.`);
    }
    const port = Number(value);
    if (!Number.isInteger(port) || port < min || port > max) {
        throw new TdkError(`${flag} must be an integer from ${min} through ${max}.`);
    }
    if (resources.some((resource) => resource.config?.port === port)) {
        throw new TdkError(`${subject} ${port} is already assigned to another resource.`);
    }
    return port;
}
export function createServiceJson(name, type, stack, port, extraFeatures = [], frameworkId, languageId, agent) {
    const framework = resolveFrontendFramework(type, frameworkId);
    // Only an explicit selection is persisted: a missing `language` has always meant Bun.
    const language = languageId === undefined ? undefined : resolveBackendLanguage(type, languageId);
    // Likewise a missing backend `framework` has always meant Hono.
    const backendFramework = resolveBackendFramework(type, frameworkId, language);
    const typeSpecific = TYPE_SPECIFIC[type];
    const base = JSON.parse(JSON.stringify(BASE_TEMPLATE));
    for (const [key, value] of Object.entries(typeSpecific)) {
        if (typeof value === "object" && value !== null && !Array.isArray(value)) {
            base[key] = { ...base[key], ...value };
        }
        else {
            base[key] = value;
        }
    }
    if (language?.devCommand) {
        base.dev = { command: language.devCommand, watch: language.watch ?? base.dev.watch };
        // The engine generates the image (.autogenerated/Dockerfile.app.autogenerated); a build
        // block would point at a Dockerfile that does not exist.
        delete base.build;
    }
    return {
        ...base,
        $schema: SERVICE_MANIFEST_SCHEMA_URL,
        schemaVersion: SERVICE_MANIFEST_SCHEMA_VERSION,
        appName: name,
        appType: type,
        featuresEnabled: [
            ...getDefaultFeaturesForResourceType(type).filter(
            // Prisma wiring is Bun-only; the Python provider owns their data layer.
            (feature) => !(language?.createFiles && feature === "prisma")),
            ...extraFeatures,
        ],
        name,
        type,
        stack,
        port,
        ...(framework ? { framework: framework.id } : {}),
        ...(backendFramework && type !== "mcp" && type !== "agent"
            ? { framework: backendFramework.id }
            : {}),
        ...(language ? { language: language.id } : {}),
        ...(type === "agent" && agent ? { agent } : {}),
    };
}
export function createByoServiceJson(name, stack, port, options) {
    return {
        $schema: SERVICE_MANIFEST_SCHEMA_URL,
        schemaVersion: SERVICE_MANIFEST_SCHEMA_VERSION,
        appName: name,
        appType: BRING_YOUR_OWN_TYPE,
        stack,
        port,
        healthCheckPath: options.healthCheckPath,
        ...(options.image ? { image: options.image } : { dockerfile: options.dockerfile }),
        ...(options.exposeViaProxy === false ? { exposeViaProxy: false } : {}),
        ...(options.restart ? { restart: options.restart } : {}),
    };
}
/**
 * The Vite configs a frontend's `dev`/`build` scripts point at are written by the engine
 * (Tilt loads the Starlark generator in `flisk up`), not by `flisk resource`. Without them
 * `vite` stops with an esbuild "Could not resolve" stack trace, so the pre-scripts say what
 * is missing instead. Inside the engine's image build the file exists and the check passes.
 */
function requireGeneratedViteConfig(configPath) {
    // The text sits inside single quotes in a shell command: no quotes, backticks or parentheses.
    const message = `${configPath} does not exist yet. Flisk engine writes it when flisk up loads this resource ` +
        "(needs Docker); flisk resource and flisk config regenerate do not create it. " +
        "Run flisk up <stack> once, or point this script at your own Vite config to build on the host.";
    return `bun -e 'if(!require("fs").existsSync(${JSON.stringify(configPath)})){console.error(${JSON.stringify(message)});process.exit(1)}'`;
}
export function createPackageJson(name, type, frameworkId, prismaEnabled = false, agentConfig, drizzleEnabled = false) {
    const isFrontend = type === "frontend";
    const framework = resolveFrontendFramework(type, frameworkId);
    const backendFramework = resolveBackendFramework(type, frameworkId);
    const isPostgresAgent = type === "agent" && agentConfig?.durability === "postgres";
    return {
        name: `@project/${name}`,
        version: "0.0.1",
        type: "module",
        scripts: {
            ...(isFrontend
                ? {
                    predev: requireGeneratedViteConfig(`${AUTOGENERATED_DIR}/vite.config.frontend.autogenerated.ts`),
                    prebuild: requireGeneratedViteConfig(`${AUTOGENERATED_DIR}/vite.config.build.autogenerated.ts`),
                }
                : {}),
            dev: isFrontend
                ? `vite --config ${AUTOGENERATED_DIR}/vite.config.frontend.autogenerated.ts`
                : "bun run --watch src/index.ts",
            build: isFrontend
                ? `tsc && vite build --config ${AUTOGENERATED_DIR}/vite.config.build.autogenerated.ts`
                : "tsc",
            // Backends and workers run `start` in their production image; doctor checks for it.
            ...(isFrontend ? {} : { start: "bun run dist/index.js" }),
            test: "vitest",
            lint: "biome check .",
            "lint:fix": "biome check . --write",
        },
        dependencies: {
            ...(isFrontend ? {} : (backendFramework?.dependencies ?? { hono: "^4.0.0" })),
            ...(framework?.dependencies ?? {}),
            ...(prismaEnabled || isPostgresAgent
                ? {
                    ...(prismaEnabled
                        ? {
                            prisma: "^7.5.0",
                            "@prisma/client": "^7.5.0",
                            "@prisma/adapter-pg": "^7.5.0",
                        }
                        : {}),
                    pg: "^8.13.0",
                }
                : {}),
            ...(drizzleEnabled ? { "drizzle-orm": DRIZZLE_ORM_RANGE, pg: PG_RANGE } : {}),
        },
        devDependencies: {
            "@types/bun": "^1.4.2",
            // The generated Docker tsconfig sets "types": ["node"]; without this the
            // image's `bun run build` fails with TS2688. ^20 matches the services that build.
            "@types/node": "^20.0.0",
            typescript: "^7.0.2",
            vitest: "^5.0.0",
            "@biomejs/biome": "^2.5.13",
            // vitest 5 peers on vite ^6.4.0 || ^7 || ^8; vite 5 makes `vitest run` fail at startup with
            // ERR_PACKAGE_PATH_NOT_EXPORTED ('./module-runner'), in every resource once it is hoisted.
            ...(isFrontend ? { vite: "^6.4.1" } : {}),
            ...(drizzleEnabled ? { "drizzle-kit": DRIZZLE_KIT_RANGE, "@types/pg": "^8.11.0" } : {}),
            ...(framework?.devDependencies ?? {}),
            ...(backendFramework?.devDependencies ?? {}),
        },
    };
}
